type TabType = "landing" | "statistik" | "pelatihan" | "ppid" | "faq";

export const Route = createFileRoute("/(core)/back-office/landing-settings/")({
  validateSearch: (search: Record<string, unknown>): { tab: TabType } => {
    const validTabs: TabType[] = [
      "landing",
      "statistik",
      "pelatihan",
      "ppid",
      "faq",
    ];
    const tabStr = (search.tab as string) || "landing";
    return {
      tab: validTabs.includes(tabStr as TabType)
        ? (tabStr as TabType)
        : "landing",
    };
  },
  beforeLoad: async ({ context }) =>
    await requirePermission(context, { permission: "banners.view" }),
  component: LandingSettingsComponent,
  head: () => pageHead("Manajemen Aset Halaman"),
});

